[dependencies]
rig = "=0.46.0"
tokio = { version = "1", features = ["full"] }
anyhow = "1"
serde = { version = "1", features = ["derive"] }
schemars = "1"

use anyhow::Result;
use rig::extractor::ExtractorBuilder;
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};


#[derive(Debug, Deserialize, Serialize, JsonSchema)]
enum Sentiment {
    Positive,
    Negative,
    Neutral,
}


#[derive(Debug, Deserialize, Serialize, JsonSchema)]
struct SentimentClassification {
    sentiment: Sentiment,
    confidence: f32,
}


#[tokio::main]
async fn main() -> Result<()> {
    let model = OpenAI::from_env()?.completion(openai::GPT_5_5);


    let classifier = ExtractorBuilder::<SentimentClassification>::new(model)
        .append_preamble("Classify the sentiment of the given text.")
        .build();


    let text = "I absolutely loved the new restaurant. The food was amazing!";
    let result = classifier.extract(text).await?.output;


    println!("Sentiment: {:?} ({:.2})", result.sentiment, result.confidence);
    Ok(())
}

#[derive(Debug, Deserialize, Serialize, JsonSchema)]
enum EntityType {
    Person,
    Organization,
    Location,
}


#[derive(Debug, Deserialize, Serialize, JsonSchema)]
struct Entity {
    text: String,
    entity_type: EntityType,
}


#[derive(Debug, Deserialize, Serialize, JsonSchema)]
struct ExtractedEntities {
    entities: Vec<Entity>,
}


let ner = ExtractorBuilder::<ExtractedEntities>::new(model)
    .append_preamble("Identify and extract people, organizations, and locations from the text.")
    .build();


let text = "Apple Inc., based in Cupertino, was founded by Steve Jobs and Steve Wozniak.";
let result = ner.extract(text).await?.output;


for entity in result.entities {
    println!("{:?}: {}", entity.entity_type, entity.text);
}

#[derive(Debug, Deserialize, Serialize, JsonSchema)]
struct TextAnalysis {
    sentiment: SentimentClassification,
    entities: Vec<Entity>,
}


let analyzer = ExtractorBuilder::<TextAnalysis>::new(model)
    .append_preamble(
        "For the given text: classify the overall sentiment with a confidence score, \
         and extract named entities (Person, Organization, Location).",
    )
    .build();


let text = "I had a great time visiting Google's headquarters in Mountain View. \
            Sundar Pichai's leadership has been impressive.";
let result = analyzer.extract(text).await?.output;


println!(
    "Sentiment: {:?} ({:.2})",
    result.sentiment.sentiment, result.sentiment.confidence
);
for entity in &result.entities {
    println!("- {:?}: {}", entity.entity_type, entity.text);
}
